const config=window.BURGER_TIN_CHECKOUT||{};
const api=String(config.apiBaseUrl||'').replace(/\/$/,'');
const expectedStoreId='glowro';
const $=selector=>document.querySelector(selector);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(value);
let token=sessionStorage.getItem('restia-store-session')||'';
let user=null,currentView='pending',currentSection='orders';
const pendingImages=new Map();
const themeStorageKey='restia-admin-theme';
const businessDays=[['mon','Lunes'],['tue','Martes'],['wed','Miércoles'],['thu','Jueves'],['fri','Viernes'],['sat','Sábado'],['sun','Domingo']];

function setAdminTheme(theme,{persist=true}={}){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';if(persist)localStorage.setItem(themeStorageKey,dark?'dark':'light');const toggle=$('#theme-toggle');if(!toggle)return;toggle.querySelector('span').textContent=dark?'Modo claro':'Modo oscuro';toggle.setAttribute('aria-label',dark?'Activar modo claro':'Activar modo oscuro');toggle.querySelector('svg').innerHTML=dark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>':'<path d="M20.7 15.1A9 9 0 0 1 8.9 3.3 9 9 0 1 0 20.7 15.1Z"/>';}
setAdminTheme(localStorage.getItem(themeStorageKey)||'light',{persist:false});
document.querySelector('#add-product-form input[name="image"]').accept='.jpg,.jpeg,.png,.webp,.avif,.gif,.bmp';

document.querySelector('.login-brand img').src='assets/restia-wordmark.png';
document.querySelector('.login-brand img').alt='Restia';
document.querySelector('.login-brand span').textContent='Tecnología para crecer.';
document.querySelector('.login-card').innerHTML=`<img class="login-store-logo" src="assets/glowro-monogram.png?v=20261027-1" alt="GlowRo"><p class="eyebrow">Administración GlowRo</p><h1>Ingresar al local</h1><p>Usá las credenciales asignadas a tu perfil.</p><form id="login-form"><label>Usuario<input name="username" required autocomplete="username" autocapitalize="none"></label><label>Contraseña<input name="password" type="password" required minlength="10" autocomplete="current-password"></label><button>Ingresar al panel</button></form><p class="error" id="login-error" role="alert"></p>`;

async function call(path,options={}){if(!config.enabled||!api.startsWith('https://'))throw new Error('El servidor todavía no está configurado.');const response=await fetch(`${api}${path}`,{...options,headers:{...options.headers,authorization:`Bearer ${token}`,'x-requested-with':'restia-web'}});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`Error ${response.status}`);return result;}
const bytesToBase64=bytes=>btoa(String.fromCharCode(...bytes));
async function deriveCredential(password,salt,iterations=120000){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:Uint8Array.from(atob(salt),char=>char.charCodeAt(0)),iterations},key,256);return bytesToBase64(new Uint8Array(bits));}
async function newCredential(password){const passwordSalt=bytesToBase64(crypto.getRandomValues(new Uint8Array(16)));return{passwordSalt,passwordVerifier:await deriveCredential(password,passwordSalt)};}
async function authenticate(username,password){const challengeResponse=await fetch(`${api}/api/auth/challenge`,{method:'POST',headers:{'content-type':'application/json','x-requested-with':'restia-web'},body:JSON.stringify({username,scope:'store'})}),challenge=await challengeResponse.json().catch(()=>({}));if(!challengeResponse.ok)throw new Error(challenge.error||'No pudimos iniciar sesión.');const passwordVerifier=await deriveCredential(password,challenge.salt,challenge.iterations);const response=await fetch(`${api}/api/auth/login`,{method:'POST',headers:{'content-type':'application/json','x-requested-with':'restia-web'},body:JSON.stringify({username,passwordVerifier,passwordSalt:challenge.salt,scope:'store'})}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'No pudimos iniciar sesión.');return result;}
function can(permission){return Boolean(user?.permissions?.includes(permission));}
function applyTheme(){document.documentElement.style.setProperty('--admin-primary','#29252a');document.documentElement.style.setProperty('--admin-accent','#b88484');}
function requestConfirmation({title,description,confirmLabel='Confirmar'}){const dialog=$('#action-dialog'),button=$('#action-dialog-confirm');dialog.returnValue='cancel';$('#action-dialog-title').textContent=title;$('#action-dialog-description').textContent=description;button.textContent=confirmLabel;return new Promise(resolve=>{dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();button.focus();});}
function statusLabel(order){if(order.status==='pending_payment')return'Mercado Pago · esperando pago';if(order.status==='confirmed')return'Pago acreditado · preparar envío';return'Cancelado';}
function orderActions(){return '';}
function orderItems(order){try{return JSON.parse(order.items_json||'[]').map(item=>`${Number(item.quantity)} × ${escapeHtml(item.name)}`).join(', ');}catch{return '';}}
function renderOrders(orders){const empty=currentView==='pending'?'No hay pedidos pendientes.':currentView==='today'?'Todavía no hay pedidos terminados hoy.':'No hay pedidos en el historial.';const card=order=>`<article class="order"><span class="tag">${escapeHtml(statusLabel(order))}</span><h2>${escapeHtml(order.code)}</h2><p><strong>${escapeHtml(order.customer_name)}</strong> · ${order.fulfillment==='delivery'?'Envío':'Retiro'}</p><p>${escapeHtml(order.address||'')}</p><p>Contacto: ${escapeHtml(order.customer_phone||'')}</p><p>${orderItems(order)}</p><p>${escapeHtml(order.notes||'')}</p><p class="total">${money(order.subtotal)}</p><p>${new Date(order.confirmed_at||order.created_at).toLocaleString('es-AR')}</p><footer>${orderActions(order)}</footer></article>`;if(!orders.length){$('#orders').className='orders';$('#orders').innerHTML=`<p class="empty">${empty}</p>`;return;}if(currentView!=='history'){$('#orders').className='orders';$('#orders').innerHTML=orders.map(card).join('');return;}const groups=orders.reduce((map,order)=>{const date=new Date(order.confirmed_at||order.created_at).toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});if(!map.has(date))map.set(date,[]);map.get(date).push(order);return map;},new Map());$('#orders').className='history-list';$('#orders').innerHTML=[...groups].map(([date,items])=>`<section class="history-day"><h2>${escapeHtml(date)}</h2><div class="orders">${items.map(card).join('')}</div></section>`).join('');}
function updateCounts(counts={}){for(const key of['pending','today','history']){$(`#count-${key}`).textContent=Number(counts[key]||0);$(`#summary-${key}`).textContent=Number(counts[key]||0);}}
async function loadOrders(){try{const result=await call(`/api/admin/orders?view=${currentView}`);renderOrders(result.orders);updateCounts(result.counts);$('#connection').textContent='Actualizado · '+new Date().toLocaleTimeString('es-AR');}catch(error){$('#connection').textContent=error.message;if(/autorizado/.test(error.message))logout('La sesión venció. Volvé a ingresar.');}}

const supportedImageTypes=new Set(['image/jpeg','image/png','image/webp','image/avif','image/gif','image/bmp']);
async function optimizeImage(file){if(!file||!supportedImageTypes.has(String(file.type).toLowerCase()))throw new Error('Formato no compatible. Usá JPG, PNG, WebP, AVIF, GIF o BMP.');if(file.size>15*1024*1024)throw new Error('La imagen original supera los 15 MB.');let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw new Error('No pudimos leer esta imagen. Probá exportarla nuevamente como JPG, PNG o WebP.');}const maxSide=1200,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.84));if(!blob||blob.size>900000)throw new Error('No pudimos reducir la imagen a menos de 900 KB. Probá con una foto más liviana.');return blob;}
async function uploadImage(id,file){const blob=await optimizeImage(file);return call(`/api/admin/products/${encodeURIComponent(id)}/image`,{method:'POST',headers:{'content-type':blob.type},body:blob});}
function renderProducts(products){for(const pending of pendingImages.values())if(pending.url)URL.revokeObjectURL(pending.url);pendingImages.clear();$('#catalog-editor').innerHTML=products.map(product=>`<form class="product-row" data-product-id="${escapeHtml(product.id)}"><div class="product-cell"><img src="${escapeHtml(product.image||'assets/glowro-monogram.png')}" alt="${escapeHtml(product.name)}" loading="lazy"><div class="product-copy"><label><span>Nombre</span><input type="text" name="name" value="${escapeHtml(product.name)}" required minlength="2" maxlength="100" aria-label="Nombre del producto"></label><label><span>Descripción</span><textarea name="description" maxlength="500" rows="2" aria-label="Descripción del producto">${escapeHtml(product.description||'')}</textarea></label></div></div><label class="price-cell"><span>Precio</span><div class="money-input"><span>$</span><input type="number" name="price" value="${Number(product.price)}" min="1" max="10000000" step="0.01" required aria-label="Precio de ${escapeHtml(product.name)}"></div></label><div class="row-photo"><span>Imagen</span><label>Reemplazar<input name="image" type="file" accept=".jpg,.jpeg,.png,.webp,.avif,.gif,.bmp"></label></div><div class="row-actions"><button type="submit">Guardar</button><button type="button" class="danger" data-delete-product>Quitar</button></div><p class="save-note" role="status"></p></form>`).join('');}
async function loadProducts(){$('#catalog-status').textContent='Cargando productos…';try{const result=await call('/api/admin/catalog');if(result.storeId!==expectedStoreId||result.storeId!==user?.storeId)throw new Error('Seguridad: el catálogo recibido no pertenece a GlowRo.');renderProducts(result.products||[]);$('#catalog-status').textContent=`${result.products?.length||0} productos activos.`;}catch(error){$('#catalog-editor').innerHTML='';$('#catalog-status').textContent=error.message;}}
function renderBusinessHours(hours={}){const days=hours.days||{};$('#business-hours').innerHTML=businessDays.map(([key,label])=>{const day=days[key]||{enabled:false,open:'09:00',close:'18:00'};return `<div class="business-day" data-day="${key}"><label class="day-toggle"><input type="checkbox" name="hours-${key}-enabled" ${day.enabled?'checked':''}><span>${label}</span></label><label><span>Desde</span><input type="time" name="hours-${key}-open" value="${escapeHtml(day.open||'09:00')}"></label><label><span>Hasta</span><input type="time" name="hours-${key}-close" value="${escapeHtml(day.close||'18:00')}"></label></div>`;}).join('');}
function readBusinessHours(form){return{enabled:form.elements.businessHoursEnabled.checked,timeZone:'America/Argentina/Buenos_Aires',days:Object.fromEntries(businessDays.map(([key])=>[key,{enabled:form.elements[`hours-${key}-enabled`].checked,open:form.elements[`hours-${key}-open`].value,close:form.elements[`hours-${key}-close`].value}]))};}
function fillStoreForm(settings){const form=$('#store-form');form.elements.business.value=settings.business||'';form.elements.phone.value=settings.phone||'';form.elements.pickupAddress.value=settings.pickupAddress||'';form.elements.deliveryZones.value=settings.deliveryZones||'';form.elements.deliveryFee.value=settings.deliveryFee??'';form.elements.businessHoursEnabled.checked=Boolean(settings.businessHours?.enabled);renderBusinessHours(settings.businessHours);form.elements.salesNotificationEmail.value=settings.salesNotificationEmail||'';form.elements.salesNotificationEnabled.checked=Boolean(settings.salesNotificationEnabled);form.elements.enableLivePayments.checked=settings.paymentMode==='production';form.elements.mpAccessToken.value='';form.elements.mpWebhookSecret.value='';form.elements.disconnectMercadoPago.checked=false;$('#mp-status').textContent=settings.mercadoPagoEnabled?(settings.paymentMode==='production'?'Cobros habilitados':'Credenciales guardadas'):'No configurado';$('#mp-status').classList.toggle('connected',Boolean(settings.mercadoPagoEnabled&&settings.paymentMode==='production'));$('#mp-webhook-url').textContent=settings.webhookUrl||'URL del webhook no disponible';$('#notification-status').textContent=settings.salesNotificationEnabled?'Activo':'Desactivado';$('#notification-status').classList.toggle('connected',Boolean(settings.salesNotificationEnabled));}
const checkMpButton=document.createElement('button');
checkMpButton.type='button';
checkMpButton.className='check-mp-button';
checkMpButton.textContent='Comprobar API de Mercado Pago';
const checkMpStatus=document.createElement('p');
checkMpStatus.className='check-mp-status';
checkMpStatus.setAttribute('role','status');
document.querySelector('.payment-guide').after(checkMpButton,checkMpStatus);
checkMpButton.addEventListener('click',async()=>{checkMpButton.disabled=true;checkMpStatus.textContent='Comprobando conexión…';try{const result=await call('/api/admin/mercadopago/check',{method:'POST'});checkMpStatus.textContent=result.message;}catch(error){checkMpStatus.textContent=error.message;}finally{checkMpButton.disabled=false;}});
async function loadStoreSettings(){try{const result=await call('/api/admin/settings');fillStoreForm(result.settings);$('#store-save-status').textContent='';}catch(error){$('#store-save-status').textContent=error.message;}}
async function loadReports(){try{const result=await call(`/api/admin/reports/summary?days=${$('#report-days').value}`),s=result.summary;$('#report-metrics').innerHTML=`<div class="metric-card"><span>Ventas confirmadas</span><strong>${s.orders}</strong></div><div class="metric-card"><span>Facturación operativa</span><strong>${money(s.revenue)}</strong></div><div class="metric-card"><span>Ticket promedio</span><strong>${money(s.averageTicket)}</strong></div><div class="metric-card"><span>Pedidos con envío</span><strong>${s.deliveryOrders}</strong></div>`;$('#top-products').innerHTML=result.topProducts.length?result.topProducts.map((item,index)=>`<div class="product-rank"><span>${index+1}</span><strong>${escapeHtml(item.name)}</strong><span>${Number(item.quantity)} u.</span></div>`).join(''):'<p class="empty">Todavía no hay ventas confirmadas en este período.</p>';}catch(error){$('#report-metrics').innerHTML=`<p class="error">${escapeHtml(error.message)}</p>`;}}

const sectionMeta={orders:['Operación diaria','Pedidos'],products:['Tienda online','Productos'],store:['Tienda','Configuración'],reports:['Inteligencia comercial','Reportes'],billing:['Administración','Facturación']};
function navigate(section){const permission=$(`[data-section="${section}"]`)?.dataset.permission;if(permission&&!can(permission))return;currentSection=section;for(const id of['orders-area','products-area','settings-area','reports-area','billing-area'])$(`#${id}`).hidden=id!==`${section==='store'?'settings':section}-area`;document.querySelectorAll('[data-section]').forEach(link=>link.classList.toggle('active',link.dataset.section===section));[$('#page-eyebrow').textContent,$('#page-title').textContent]=sectionMeta[section];$('#refresh').hidden===false;$('#sidebar').classList.remove('open');if(section==='orders')loadOrders();if(section==='products')loadProducts();if(section==='store')loadStoreSettings();if(section==='reports')loadReports();}
async function forcePasswordChange(){if(!user?.mustChangePassword)return;const challengeResponse=await fetch(`${api}/api/auth/challenge`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:user.username,scope:'store'})}),challenge=await challengeResponse.json().catch(()=>({}));if(!challengeResponse.ok)throw new Error(challenge.error||'No pudimos preparar el cambio de contraseña.');const dialog=document.createElement('dialog');dialog.className='password-dialog';dialog.innerHTML=`<form><p class="eyebrow">Primer ingreso</p><h2>Creá tu contraseña definitiva</h2><p>Debe tener al menos 10 caracteres y ser distinta de la contraseña temporal.</p><label>Nueva contraseña<input name="password" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><label>Repetir contraseña<input name="confirm" type="password" minlength="10" maxlength="128" required autocomplete="new-password"></label><p class="error" role="alert"></p><button>Guardar contraseña</button></form>`;document.body.append(dialog);dialog.showModal();await new Promise(resolve=>dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,password=form.elements.password.value;if(password!==form.elements.confirm.value){form.querySelector('.error').textContent='Las contraseñas no coinciden.';return;}const button=form.querySelector('button');button.disabled=true;try{const credential=await newCredential(password),comparisonVerifier=await deriveCredential(password,challenge.salt,challenge.iterations);await call('/api/auth/change-password',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...credential,comparisonVerifier})});user.mustChangePassword=false;dialog.close();dialog.remove();resolve();}catch(error){form.querySelector('.error').textContent=error.message;button.disabled=false;}}));}
async function startSession(){const result=await call('/api/admin/session');user=result.user;if(user.storeId!=='glowro')throw new Error('Este panel es exclusivo de GlowRo.');sessionStorage.setItem('restia-store-session',token);$('#user-name').textContent=user.name;$('#user-role').textContent=user.role;$('#user-avatar').textContent=(user.name||'A').trim().charAt(0).toUpperCase();document.querySelectorAll('[data-permission]').forEach(item=>item.hidden=!can(item.dataset.permission));$('#clear-history').hidden=!can('orders:manage');$('#login').hidden=true;$('#app-shell').hidden=false;await forcePasswordChange();let first=['orders','products','reports','billing','store'].find(section=>{const permission=$(`[data-section="${section}"]`)?.dataset.permission;return !permission||can(permission);})||'orders';navigate(first);applyTheme();}
async function logout(message=''){if(token)call('/api/auth/logout',{method:'POST'}).catch(()=>{});token='';user=null;sessionStorage.removeItem('restia-store-session');sessionStorage.removeItem('burger-tin-staff-token');$('#app-shell').hidden=true;$('#login').hidden=false;$('#login-error').textContent=message;}

$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button'),data=new FormData(event.currentTarget);button.disabled=true;button.textContent='Verificando…';$('#login-error').textContent='';try{const result=await authenticate(data.get('username'),data.get('password'));token=result.session;user=result.user;sessionStorage.setItem('restia-store-session',token);await startSession();}catch(error){token='';$('#login-error').textContent=error.message;}finally{button.disabled=false;button.textContent='Ingresar al panel';}});
$('#logout').addEventListener('click',async()=>{if(await requestConfirmation({title:'¿Cerrar sesión?',description:'Vas a salir del panel de administración. Para volver a ingresar necesitarás tu usuario y contraseña.',confirmLabel:'Sí, salir'}))logout();});$('#theme-toggle').addEventListener('click',()=>setAdminTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.querySelector('.side-nav').addEventListener('click',event=>{const button=event.target.closest('[data-section]');if(button)navigate(button.dataset.section);});$('#refresh').addEventListener('click',()=>navigate(currentSection));
document.querySelector('.views').addEventListener('click',event=>{const button=event.target.closest('[data-view]');if(!button)return;currentView=button.dataset.view;document.querySelectorAll('.view').forEach(item=>item.classList.toggle('active',item===button));$('#history-tools').hidden=currentView!=='history';loadOrders();});
$('#store-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),data=new FormData(form);button.disabled=true;button.textContent='Guardando…';try{const result=await call('/api/admin/settings',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({business:data.get('business'),phone:data.get('phone'),pickupAddress:data.get('pickupAddress'),deliveryZones:data.get('deliveryZones'),deliveryFee:data.get('deliveryFee'),businessHours:readBusinessHours(form),salesNotificationEmail:data.get('salesNotificationEmail'),salesNotificationEnabled:data.has('salesNotificationEnabled'),enableLivePayments:data.has('enableLivePayments'),mpAccessToken:data.get('mpAccessToken'),mpWebhookSecret:data.get('mpWebhookSecret'),disconnectMercadoPago:data.has('disconnectMercadoPago')})});fillStoreForm(result.settings);$('#store-save-status').textContent='✓ Configuración publicada';}catch(error){$('#store-save-status').textContent=error.message;}finally{button.disabled=false;button.textContent='Guardar configuración';}});
$('#show-add-product').addEventListener('click',()=>{$('#add-product-form').hidden=false;$('#add-product-form').elements.name.focus();});$('#cancel-add-product').addEventListener('click',()=>{$('#add-product-form').reset();$('#add-product-form').hidden=true;});
$('#add-product-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),note=form.querySelector('.save-note'),data=new FormData(form);button.disabled=true;try{const result=await call('/api/admin/products',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:data.get('name'),description:data.get('description'),price:Number(data.get('price'))})});const file=form.elements.image.files?.[0];if(file)await uploadImage(result.id,file);form.reset();form.hidden=true;await loadProducts();}catch(error){note.textContent=error.message;}finally{button.disabled=false;}});
$('#catalog-editor').addEventListener('change',event=>{if(event.target.name!=='image'||!event.target.files?.[0])return;const row=event.target.closest('.product-row'),note=row.querySelector('.save-note'),file=event.target.files[0];if(!supportedImageTypes.has(String(file.type).toLowerCase())||file.size>15*1024*1024){note.textContent=file.size>15*1024*1024?'La imagen supera los 15 MB.':'Formato no compatible. Usá JPG, PNG, WebP, AVIF, GIF o BMP.';event.target.value='';return;}const previous=pendingImages.get(row.dataset.productId);if(previous?.url)URL.revokeObjectURL(previous.url);const url=URL.createObjectURL(file);pendingImages.set(row.dataset.productId,{file,url});row.querySelector('img').src=url;note.textContent='Foto lista. Presioná Guardar para publicarla.';});
$('#catalog-editor').addEventListener('submit',async event=>{event.preventDefault();const row=event.target.closest('.product-row'),id=row.dataset.productId,button=row.querySelector('[type="submit"]'),note=row.querySelector('.save-note'),data=new FormData(row);button.disabled=true;try{await call(`/api/admin/products/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({name:data.get('name'),description:data.get('description'),price:Number(data.get('price'))})});const pending=pendingImages.get(id);if(pending){const result=await uploadImage(id,pending.file);row.querySelector('img').src=result.image;URL.revokeObjectURL(pending.url);pendingImages.delete(id);}note.textContent='✓ Publicado';}catch(error){note.textContent=error.message;}finally{button.disabled=false;}});
$('#catalog-editor').addEventListener('click',async event=>{const button=event.target.closest('[data-delete-product]');if(!button)return;const row=button.closest('.product-row');if(!confirm(`¿Quitar “${row.elements.name.value}” del menú?`))return;button.disabled=true;try{await call(`/api/admin/products/${encodeURIComponent(row.dataset.productId)}`,{method:'DELETE'});row.remove();}catch(error){row.querySelector('.save-note').textContent=error.message;button.disabled=false;}});
$('#clear-history').addEventListener('click',async()=>{if(!confirm('¿Borrar el historial y reiniciar la numeración en GR-000001?'))return;try{await call('/api/admin/history',{method:'DELETE'});await loadOrders();}catch(error){alert(error.message);}});$('#orders').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='cancel'&&!await requestConfirmation({title:`¿Cancelar el pedido ${button.dataset.code}?`,description:'El pedido desaparecerá de Pendientes, no se imprimirá y quedará registrado como cancelado.',confirmLabel:'Sí, cancelar pedido'}))return;button.disabled=true;try{await call(`/api/admin/orders/${encodeURIComponent(button.dataset.code)}/${button.dataset.action}`,{method:'POST'});await loadOrders();}catch(error){alert(error.message);}finally{button.disabled=false;}});$('#report-days').addEventListener('change',loadReports);
if(token)startSession().catch(()=>logout('La sesión venció. Volvé a ingresar.'));setInterval(()=>{if(token&&currentSection==='orders')loadOrders();},15000);
